"""Additive management cockpit over existing reads; no new network or order path."""
CSS=r'''
body.cc{background:radial-gradient(ellipse at 10% 0,#214b6440,transparent 46%),#0a141e}body.cc main{max-width:1600px;padding:24px 38px 70px}.office-heading{padding:18px 0 24px;border-bottom:1px solid #2d4557;gap:16px;flex-wrap:wrap}.office-heading h1{font-size:clamp(32px,3.4vw,46px);font-weight:550;letter-spacing:-.05em}.office-heading p{line-height:1.6}.office-heading>a{border-radius:9px;padding:11px 14px}.office-account{background:linear-gradient(115deg,#20394a,#132530)!important}.office-layout{grid-template-columns:minmax(0,1fr) 348px;gap:28px}.office-side{box-shadow:0 15px 60px #0003}.office-side .cc-stage{height:215px;min-height:215px!important}.office-side #talk header h3{font-size:19px}.office-summary{border:0;border-bottom:1px solid #304659;border-radius:0;background:transparent;padding-bottom:16px}.office-metric{padding:12px 20px}.office-metric:first-child{padding-left:0}.office-metric small{text-transform:uppercase;letter-spacing:.08em;font-size:9px}.office-metric strong{font-size:30px;font-weight:550}.work-list{border:0;background:transparent;overflow:visible}.work-item{border:1px solid #314b5e;border-radius:16px;margin-bottom:12px;background:linear-gradient(115deg,#192c3c,#11212e)}.work-item+.work-item{border-top:1px solid #314b5e}.work-item>summary{padding:20px;gap:18px}.work-name h3{font-size:17px;line-height:1.4}.work-name p{font-size:11px;line-height:1.55}.work-avatar{display:grid!important;flex-basis:44px;height:44px;border-radius:11px}.club-logo{position:relative;overflow:hidden}.club-logo img{position:absolute;width:38px;height:38px;object-fit:contain;background:#f5f7fa}.work-number strong{font-size:24px}.work-detail{padding:23px;border-radius:0 0 16px 16px}.work-rationale{max-width:70ch}.work-detail .work-metrics{border-top:1px solid #2b4255;border-bottom:1px solid #2b4255;padding:17px 0;margin:14px 0}.office-orders td{padding:14px 8px;font-variant-numeric:tabular-nums}.office-orders th{text-transform:uppercase;letter-spacing:.08em;font-size:9px}.mg-tools{order:-2;display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;margin-bottom:17px}.mg-tools nav,.mg-tools div{display:flex;gap:7px;flex-wrap:wrap}.mg-tools button,.mg-select,.mg-compare button{font:500 11px var(--display);min-height:38px;padding:9px 12px;border:1px solid #3b566a;border-radius:9px;background:#142c3d;color:#daebf6;cursor:pointer}.mg-tools button[aria-pressed=true],.mg-select[aria-pressed=true]{background:#d0e8f5;color:#122a3b}.mg-select{min-height:30px;padding:5px 8px;margin-top:8px;font-size:10px}.mg-compare{order:-1;border:1px solid #46637b;border-radius:16px;background:#112534;padding:20px;margin-bottom:22px}.mg-compare[hidden]{display:none}.mg-compare>header{display:flex;justify-content:space-between;align-items:center;gap:10px;margin-bottom:14px}.mg-compare h2{font:550 18px var(--display);margin:0}.mg-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:12px}.mg-grid article{min-width:0;padding:15px;border:1px solid #345268;background:#182f40;border-radius:11px;overflow-wrap:anywhere}.mg-grid h3{font:550 15px/1.5 var(--display);margin:0 0 13px}.mg-grid dl{margin:0}.mg-grid dt{font:10px var(--display);color:#a1bed1;margin-top:12px}.mg-grid dd{font:500 12px/1.5 var(--display);color:#e9f3fa;margin:4px 0}.mg-grid button{margin-top:14px}.mg-note{font:11px/1.6 var(--display);color:#a7bfd2}.mg-notice{order:-1;color:#f5cd95;font:12px var(--display)}.office-board[data-mg-view=work]>.desk-activity,.office-board[data-mg-view=work]>.cap-panel,.office-board[data-mg-view=activity]>#office-content,.office-board[data-mg-view=activity]>.desk-toolbar,.office-board[data-mg-view=activity]>.desk-brief,.office-board[data-mg-view=activity]>.desk-no-match,.office-board[data-mg-view=activity]>.cap-panel,.office-board[data-mg-view=learning]>#office-content,.office-board[data-mg-view=learning]>.desk-toolbar,.office-board[data-mg-view=learning]>.desk-brief,.office-board[data-mg-view=learning]>.desk-no-match,.office-board[data-mg-view=learning]>.desk-activity{display:none!important}.office-board[data-mg-density=compact] .work-item>summary{padding:12px 16px}.office-board[data-mg-density=compact] .work-name h3{font-size:15px}.office-board[data-mg-density=compact] .work-number strong{font-size:20px}
@media(max-width:1100px){body.cc main{padding:20px}.office-layout{grid-template-columns:minmax(0,1fr) 305px;gap:18px}.work-item>summary{gap:12px;padding:17px}}
@media(max-width:800px){body.cc main{padding:14px 14px 90px}.office-layout{display:flex}.office-heading{padding:14px 0;gap:9px}.office-heading h1{font-size:32px}.office-heading>a{font-size:11px;padding:9px 11px}.mg-tools button{min-height:42px}.mg-grid{grid-template-columns:1fr}.mg-grid article{display:grid;grid-template-columns:1fr 1.3fr;gap:10px}.mg-grid dl{display:grid;grid-template-columns:1fr 1fr;gap:7px}.mg-grid dt,.mg-grid dd{margin:0}.mg-grid button{grid-column:1/-1}.office-metric{padding:12px}.office-metric strong{font-size:22px}.work-item>summary{padding:16px;gap:12px}.office-side .cc-stage{height:136px;min-height:136px!important}.work-detail{padding:17px}.mg-compare{padding:15px}}
@media(prefers-reduced-motion:reduce){.work-item>summary{transition:none}.office-side .talk-log{scroll-behavior:auto}}
'''
JS=r'''
(function(){
'use strict';
var board=document.querySelector('.office-board'),content=document.getElementById('office-content');if(!board||!content||!window.CCOffice)return;
var kind=document.body.dataset.kind,name=kind[0].toUpperCase()+kind.slice(1),rows=[],selected=new Set(),last=null,readAt=null;
var E=function(v){return String(v==null?'Not recorded':v).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];});};
function data(s){return s&&(s.status==='OK'||s.status==='EMPTY')?s.data:null;}function list(s){var a=data(s);return Array.isArray(a)?a:[];}function num(v){return typeof v==='number'&&Number.isFinite(v);}function money(v){return num(v)?new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(v):'Not recorded';}function human(v){return String(v||'Not recorded').replace(/_/g,' ').toLowerCase();}function when(v){var d=new Date(typeof v==='number'?v*1000:v);return v!=null&&Number.isFinite(d.getTime())?d.toISOString():'Not recorded';}function title(r){return (r.label||{}).participant||(r.market||{}).selection||r.us_market_slug||human(r.kind||r.category);}
var tools=document.createElement('div');tools.className='mg-tools';tools.innerHTML='<nav aria-label="Office views"><button type="button" data-mg-view="work" aria-pressed="true">Workboard</button><button type="button" data-mg-view="activity" aria-pressed="false">Activity</button><button type="button" data-mg-view="learning" aria-pressed="false">Work & learning</button></nav><div><button type="button" id="mg-density" aria-pressed="false">Compact view</button><button type="button" id="mg-export">Meeting brief ↓</button></div>';board.prepend(tools);
var compare=document.createElement('section');compare.className='mg-compare';compare.hidden=true;compare.setAttribute('aria-label','Compare recorded work');tools.after(compare);var notice=document.createElement('p');notice.className='mg-notice';notice.setAttribute('role','status');notice.hidden=true;compare.after(notice);
function view(v){board.dataset.mgView=v;tools.querySelectorAll('[data-mg-view]').forEach(function(b){b.setAttribute('aria-pressed',String(b.dataset.mgView===v));});}view('work');
tools.addEventListener('click',function(e){var b=e.target.closest('[data-mg-view]');if(b)view(b.dataset.mgView);});document.addEventListener('click',function(e){if(e.target.closest('a[href="#agent-capabilities"]'))view('learning');});
document.getElementById('mg-density').onclick=function(){var compact=board.dataset.mgDensity!=='compact';board.dataset.mgDensity=compact?'compact':'comfortable';this.setAttribute('aria-pressed',String(compact));this.textContent=compact?'Comfortable view':'Compact view';};
function records(j){if(kind==='xavier')return list(j.owned_positions).filter(function(p){return p.remaining&&p.remaining.open_qty>0;}).map(function(p){var r=p.remaining,rc=p.recommendation||{},orders=list(j.standing_orders).filter(function(o){return o.group_id===p.group_id&&o.open===true;});return {id:p.group_id,title:title(p),source:p,fields:[['Cost basis',money(r.cost_basis_usd)],['Marked value',money(r.marked_value_usd)],['Unrealized P&L',money(r.unrealized_pnl_usd)],['Exit decision',human(rc.recommendation)],['Working orders',orders.length?orders.map(function(o){return human(o.direction)+' '+(num(o.qty)&&num(o.filled_qty)?Math.max(0,o.qty-o.filled_qty):'?')+' @ '+money(o.limit_price);}).join('; '):r.open_management_orders===0?'None':'Detail unavailable'],['Review time',when(rc.reviewed_at)]]};});
if(kind==='derek')return (j.strategies||[]).flatMap(function(s){return list(s.recent).map(function(r){return {id:r.decision_id,title:title(r),source:r,fields:[['Decision',human(r.verdict)],['Gross edge',num(r.edge_pp)?r.edge_pp.toFixed(2)+' pp':'Not recorded'],['Net EV',money(r.net_ev_usd)],['Price',money(r.purchase_price)],['Policy',r.policy_version||'Not recorded'],['Evaluated',when(r.decided_at)]]};});});
return list(j.operational_audit).map(function(r){var ev=r.events||[];return {id:r.recommendation_id,title:title(r),source:r,fields:[['Owner',r.owner_agent||'Unassigned'],['Status',human(r.status)],['Genuine reviews',ev.filter(function(e){return e.kind==='RESPONSE'&&e.actor!=='SYSTEM';}).length],['Measurements',ev.filter(function(e){return /MEASUR/.test(e.kind);}).length],['Created',when(r.created_at)]]};});}
function decorate(){content.querySelectorAll('.work-item[data-work-key]').forEach(function(el){var r=rows.find(function(r){return r.id===el.dataset.workKey;});if(!r)return;var b=el.querySelector('.mg-select');if(!b){b=document.createElement('button');b.type='button';b.className='mg-select';b.dataset.mgSelect=r.id;(el.querySelector('.work-name>div')||el.querySelector('summary')).append(b);}b.textContent=selected.has(r.id)?'Selected ✓':'Compare +';b.setAttribute('aria-pressed',String(selected.has(r.id)));b.setAttribute('aria-label','Compare '+r.title);});}
function show(){var rs=rows.filter(function(r){return selected.has(r.id);});compare.hidden=!rs.length;compare.innerHTML=rs.length?'<header><h2>Side by side · '+rs.length+' / 3</h2><button type="button" data-mg-clear>Clear</button></header><div class="mg-grid">'+rs.map(function(r){return '<article><h3>'+E(r.title)+'</h3><dl>'+r.fields.map(function(f){return '<dt>'+E(f[0])+'</dt><dd>'+E(f[1])+'</dd>';}).join('')+'</dl><button type="button" data-mg-ask="'+E(r.id)+'">Ask '+E(name)+' ↗</button></article>';}).join('')+'</div><p class="mg-note">'+(last&&last.fail?'STALE · Last successful records. ':'')+'Recorded snapshot. An unfilled order is not a realized return. Selection stays in this tab only.</p>':'';}
board.addEventListener('click',function(e){var b=e.target.closest('[data-mg-select],[data-mg-clear],[data-mg-ask]');if(!b)return;e.preventDefault();e.stopPropagation();notice.hidden=true;if(b.hasAttribute('data-mg-clear'))selected.clear();else if(b.hasAttribute('data-mg-select')){var id=b.dataset.mgSelect;if(selected.has(id))selected.delete(id);else if(selected.size<3)selected.add(id);else{notice.hidden=false;notice.textContent='Select up to three records. Remove one to compare another.';return;}}else{document.getElementById('talk-in').value='Explain the recorded evidence, current action, uncertainty and next review for record '+b.dataset.mgAsk+'.';if(window.CCDesk)CCDesk.openConversation();return;}decorate();show();});
function update(st){if(st&&st.json){if(last&&last.json&&last.json.account_id!==st.json.account_id)selected.clear();last=st;readAt=st.okAt;rows=records(st.json);}else if(st&&st.fail)last=Object.assign({},last||{},{fail:st.fail});selected.forEach(function(id){if(!rows.some(function(r){return r.id===id;}))selected.delete(id);});decorate();show();}
var old=CCOffice.render;CCOffice.render=function(st){old(st);update(st);};var panels=CC.ops.panels;CC.ops.panels=function(k,st){var result=panels(k,st);if(k===kind)update(st);return result;};
document.getElementById('mg-export').onclick=function(){if(!last||!last.json){notice.hidden=false;notice.textContent='A workspace record is required to export.';return;}var a=data(last.json.account),rs=selected.size?rows.filter(function(r){return selected.has(r.id);}):rows,html='<!doctype html><html lang="en"><meta charset="utf-8"><title>'+E(name)+' meeting brief</title><style>body{font:15px/1.6 system-ui;color:#183347;max-width:960px;margin:40px auto;padding:24px}h1{font-size:38px;letter-spacing:-1px}table{width:100%;border-collapse:collapse}td,th{text-align:left;border-bottom:1px solid #d7e2e8;padding:9px}article{break-inside:avoid;margin-top:30px}small{color:#536d7c}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:11px}</style><h1>'+E(name)+' · Management briefing</h1><p>Simulated execution · '+(last.fail?'STALE: last successful snapshot':'Recorded workspace snapshot')+'</p><small>Exported '+E(new Date().toISOString())+' · Records read '+E(when(readAt))+'</small><h2>Account in this snapshot</h2>'+(a?'<table>'+Object.entries(a).filter(function(f){return /_usd$/.test(f[0]);}).map(function(f){return '<tr><th>'+E(human(f[0]))+'</th><td>'+E(money(f[1]))+'</td></tr>';}).join('')+'</table>':'<p>Account unavailable. No balance inferred from cards.</p>')+rs.map(function(r){return '<article><h2>'+E(r.title)+'</h2><small>'+E(r.id)+'</small><table>'+r.fields.map(function(f){return '<tr><th>'+E(f[0])+'</th><td>'+E(f[1])+'</td></tr>';}).join('')+'</table></article>';}).join('')+'<p>'+rs.length+' records from this read, not the full historical ledger. Quotes and working orders are not guaranteed execution.</p><details><summary>Source records</summary><pre>'+E(JSON.stringify({account:a,read_at:readAt,read_failure:last.fail||null,records:rs.map(function(r){return r.source;})},null,2))+'</pre></details></html>';var u=URL.createObjectURL(new Blob([html],{type:'text/html;charset=utf-8'})),link=document.createElement('a');link.href=u;link.download='BettorToken-'+name+'-brief.html';link.click();setTimeout(function(){URL.revokeObjectURL(u);},1000);};
window.CCManagement={render:update,view:view};
})();
'''
